sketches.source:
setcpm(80/4)

// The lead sings the tune: Bb, G7, C7, F7, Bb, C7, F7, Bb
lead: note("<[d4@2 c4 bb3 d4@2 f4@2] [d4@4 b3@4] [c4@2 d4 e4 g4@2 e4@2] [eb4@4 c4@4] [d4@2 f4@2 bb4@2 a4 g4] [f4@4 e4@4] [eb4@2 d4@2 c4@2 a3@2] [bb3@8]>")
  .s("voice").syl("<[la@2 li la lo@2 ma@2] [ho@4 nu@4] [wa@2 la ro mi@2 nu@2] [so@4 mu@4] [la@2 di@2 lo@2 ma ri] [mo@4 nu@4] [ho@2 na@2 so@2 wa@2] [ho@8]>")
  .mono(1).vglide(.12).attack(.08).release(.4).room(.3).gain(.3)

// Tenor, baritone and bass ring the chords around it
harmony: note("<[bb2,f3,f4] [g2,f3,d4] [c3,g3,bb3] [f2,c3,a3] [bb2,f3,d4] [c3,g3,bb3] [f2,a3,f4] [bb2,f3,d4,f4]>")
  .s("ooh").attack(.2).release(.6).room(.3).gain(.22)

// Footsteps on the boardwalk
steps: s("step ~ ~ ~ step ~ ~ ~").distance(6).gain(.1)

setcpm(132/4)

// Left-hand boogie figures for G, C and D
const lg = note("g1 b1 d2 e2 f2 e2 d2 b1")
const lc = note("c2 e2 g2 a2 bb2 a2 g2 e2")
const ld = note("d2 f#2 a2 b2 c3 b2 a2 f#2")
// Right-hand chords
const rg = note("[b4,d5,f5,g5]")
const rc = note("[bb4,c5,e5,g5]")
const rd = note("[a4,c5,d5,f#5]")

// Twelve bars, eight to the bar
left: cat(lg, lg, lg, lg, lc, lc, lg, lg, ld, lc, lg, ld).swing(4)
  .s("triangle").timbre("bright").decay(.25).sustain(.2).lpf(1800).gain(.35)
right: cat(rg, rg, rg, rg, rc, rc, rg, rg, rd, rc, rg, rd)
  .struct("x [~@2 x] ~ [~@2 x]")
  .s("triangle").timbre("bright").decay(.2).sustain(.1).lpf(3000).gain(.2)

// Close-harmony voices on the off-beats
voices: note("<[b3,d4,g4] [b3,d4,g4] [b3,d4,g4] [b3,d4,g4] [c4,e4,g4] [c4,e4,g4] [b3,d4,g4] [b3,d4,g4] [a3,d4,f#4] [c4,e4,g4] [b3,d4,g4] [a3,d4,f#4]>")
  .struct("~ [x@2 x] ~ x").s("ooh").attack(.02).release(.3).room(.3).gain(.2)

// A shuffle beat
drums: s("bd ~ bd ~, ~ sd ~ sd, [hh@2 hh]*4").gain(.45)

setcpm(72/4)

// Triplet piano: C, Am, F, G
piano: note("<[c4,e4,g4] [a3,c4,e4] [a3,c4,f4] [b3,d4,g4]>").struct("[x x x]*4")
  .s("triangle").timbre("bright").decay(.15).sustain(.1).release(.1).lpf(2600).gain(.18)

// A walking bass
bass: note("<[c2 e2 g2 e2] [a1 c2 e2 c2] [f1 a1 c2 a1] [g1 b1 d2 b1]>")
  .s("sine").shape(.15).decay(.3).sustain(.4).gain(.5)

// A backbeat with triplet hats
drums: stack(
  s("bd ~ bd ~").gain(.5),
  s("~ sd ~ sd").room(.2).gain(.45),
  s("[hh hh hh]*4").hpf(6000).gain(.2)
)

// The group sings ooh, ooh-ooh
backing: note("<[e3,g3,c4] [e3,a3,c4] [f3,a3,c4] [d3,g3,b3]>").struct("x@2 x x@3 x x")
  .s("ooh").attack(.03).release(.3).room(.4).gain(.2)

// A honking tenor sax
sax: note("<[g4@2 e4 g4 c5@4] [a4@2 c5 e5 c5@4] [a4@2 f4 a4 c5@2 a4@2] [b4@2 d5 b4 g4@4]>")
  .s("sawtooth").timbre("reed").vowel("o").lpf(2200).vib(5).vibdepth(.15)
  .attack(.02).sustain(.6).release(.15).pan(.6).gain(.22)

setcpm(90/4)

// Dusty, swung drums
drums: stack(
  s("bd ~ ~ bd ~ ~ bd ~, ~ ~ sd ~ ~ ~ sd ~").swing(4).crush(10).lpf(4500).gain(.75),
  s("hh*8").swing(4).hpf(6000).gain("[.3 .15]*4")
)

// A jazz loop off an old record: Dm7, Dm7, Gm7, A7
loop: note("<[d3,f3,a3,c4] [d3,f3,a3,c4] [g3,bb3,d4,f4] [a3,c#4,e4,g4]>").struct("x ~ ~ x ~ x ~ ~").swing(4)
  .s("sine").fm(1.1).fmh(2).trem(5).tremdepth(.2).crush(7)
  .lpf(1800).decay(.6).sustain(.3).release(.4).gain(.3)

// An upright bass
bass: note("<[d2 ~ ~ d2 ~ ~ a1 c2] [d2 ~ ~ d2 ~ f2 e2 c2] [g1 ~ ~ g1 ~ ~ f1 g1] [a1 ~ ~ a1 ~ c#2 e2 a1]>").swing(4)
  .s("sine").shape(.1).decay(.4).sustain(.3).release(.1).gain(.55)

// A horn sample on the turnaround
horns: note("<~ ~ ~ [~ ~ ~ ~ [c#5,e5] ~ [e5,g5] ~]>")
  .s("sawtooth").timbre("reed").crush(8).lpf(2000).decay(.2).sustain(.3).room(.3).gain(.18)

// Vinyl crackle
crackle: s("click*16?0.3").hpf(3000).gain(rand.range(.03, .1))
